const compactSubject = (code?: string | null, name?: string | null) => { const raw = (code || name || "").replace(/^CBC[-_\s]*/i, "").trim(); const key = raw.toLowerCase().replace(/[-_]/g, " ").replace(/\s+/g, " "); const aliases: Record<string,string> = { kiswahili: "KISW", english: "ENG", mathematics: "MAT", "integrated science": "INT SCI", "social studies": "SST", "religious education": "CRE", "creative arts": "C ART", agriculture: "AGRI", "pre technical studies": "PRE TECH", "life skills education": "LIFE SKILLS", "health education": "HEALTH" }; return aliases[key] || raw.toUpperCase().slice(0, 12); };

